func testBaseWiFiNetworkDiagnosticsInit() {
    let controller = MTRDeviceController()
    let device = MTRDevice(nodeID: n(1), controller: controller)
    let baseDevice: MTRBaseDevice = device
    _ = (device, baseDevice)
    _ = MTRBaseClusterWiFiNetworkDiagnostics(device: baseDevice, endpoint: 1, queue: DispatchQueue.global())
    _ = MTRBaseClusterWiFiNetworkDiagnostics(device: baseDevice, endpointID: n(1), queue: DispatchQueue.global())
}

