func testBaseWiFiNetworkDiagnosticsCommandFailClosed() {
    let controller = MTRDeviceController()
    let device = MTRDevice(nodeID: n(1), controller: controller)
    let baseDevice: MTRBaseDevice = device
    _ = (device, baseDevice)
    guard let cluster = MTRBaseClusterWiFiNetworkDiagnostics(device: baseDevice, endpointID: n(1), queue: DispatchQueue.global()) else {
        mtrRequire(false, "MTRBaseClusterWiFiNetworkDiagnostics init")
        return
    }
    cluster.resetCounts(completion: { err in mtrExpectInvalidState(err) })
    cluster.resetCounts(completionHandler: { err in mtrExpectInvalidState(err) })
    cluster.resetCounts(with: MTRWiFiNetworkDiagnosticsClusterResetCountsParams(), completion: { err in mtrExpectInvalidState(err) })
    cluster.resetCounts(with: MTRWiFiNetworkDiagnosticsClusterResetCountsParams(), completionHandler: { err in mtrExpectInvalidState(err) })
}

